/**
 * useResolvedAdvertorialConfig
 * 
 * Resolves dynamic placeholders in AdvertorialConfig strings at render time.
 * This prevents price/count drift when values change — configs use placeholders
 * like {{price}}, {{count}}, {{countFull}} that get replaced with live data.
 * 
 * Supported placeholders:
 *   {{price}}      → locale-formatted 1x Standard price (e.g., "$69.90", "£69.90", "69,90 €")
 *   {{count}}      → short customer count (e.g., "770K+")
 *   {{countFull}}  → full customer count (e.g., "770,000+")
 * 
 * Usage:
 *   const resolvedConfig = useResolvedAdvertorialConfig(neckPainConfessionConfig);
 *   // resolvedConfig.articleTitle now has live prices and counts
 */

import { useMemo } from 'react';
import type { AdvertorialConfig } from '@/config/types';
import { useLocalePricing } from '@/hooks/useLocalePricing';
import { useCustomerCount, formatShort } from '@/components/CustomerCount';

export function useResolvedAdvertorialConfig(config: AdvertorialConfig): AdvertorialConfig {
  const { standardPricing, fp } = useLocalePricing();
  const customerCount = useCustomerCount();

  return useMemo(() => {
    const price1x = fp(standardPricing[0].price);
    const countShort = `${formatShort(customerCount)}+`;
    const countFull = `${customerCount.toLocaleString('en-US')}+`;

    const resolve = (str: string): string =>
      str
        .replace(/\{\{price\}\}/g, price1x)
        .replace(/\{\{count\}\}/g, countShort)
        .replace(/\{\{countFull\}\}/g, countFull);

    return {
      ...config,
      articleTitle: resolve(config.articleTitle),
      articleTitleHighlight: config.articleTitleHighlight
        ? resolve(config.articleTitleHighlight)
        : undefined,
      articleSubtitle: resolve(config.articleSubtitle),
      seo: {
        ...config.seo,
        title: resolve(config.seo.title),
        description: resolve(config.seo.description),
      },
    };
  }, [config, standardPricing, fp, customerCount]);
}
